using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Storage.ValueConversion;
using Microsoft.EntityFrameworkCore.Diagnostics;
using PersonalOrderDesk.Domain;
namespace PersonalOrderDesk.Data;

public sealed class DeskDbContext(DbContextOptions<DeskDbContext> options) : DbContext(options)
{
    public DbSet<WorkItem> WorkItems => Set<WorkItem>();
    public DbSet<WorkItemRelation> WorkItemRelations => Set<WorkItemRelation>();
    public DbSet<PaymentTransaction> PaymentTransactions => Set<PaymentTransaction>();
    public DbSet<PaymentAllocation> PaymentAllocations => Set<PaymentAllocation>();
    public DbSet<ExpenseGroup> ExpenseGroups => Set<ExpenseGroup>();
    public DbSet<Expense> Expenses => Set<Expense>();
    public DbSet<Shipment> Shipments => Set<Shipment>();
    public DbSet<WorkStatusHistory> WorkStatusHistories => Set<WorkStatusHistory>();
    public DbSet<ActivityLog> ActivityLogs => Set<ActivityLog>();
    public DbSet<ImportBatch> ImportBatches => Set<ImportBatch>();
    public DbSet<ImportRowMapping> ImportRowMappings => Set<ImportRowMapping>();
    public DbSet<Setting> Settings => Set<Setting>();
    protected override void OnConfiguring(DbContextOptionsBuilder b) { if (b.IsConfigured) b.AddInterceptors(new ForeignKeysInterceptor()); }
    protected override void OnModelCreating(ModelBuilder b)
    {
        foreach (var e in b.Model.GetEntityTypes()) foreach (var p in e.GetProperties()) if (p.ClrType.IsEnum) p.SetValueConverter(typeof(EnumToStringConverter<>).MakeGenericType(p.ClrType));
        b.Entity<WorkItem>().HasQueryFilter(x => !x.IsDeleted);
        b.Entity<WorkItem>().HasIndex(x => x.IsDeleted);
        b.Entity<WorkItem>().HasIndex(x => x.BusinessOrderNo); b.Entity<WorkItem>().HasIndex(x => x.WorkStatus); b.Entity<WorkItem>().HasIndex(x => x.IsArchived); b.Entity<WorkItem>().HasIndex(x => x.ReceivedDate); b.Entity<WorkItem>().HasIndex(x => x.EffectiveDueDate);
        b.Entity<WorkItem>().Property(x => x.Version).IsConcurrencyToken(); b.Entity<WorkItem>().HasOne<ImportBatch>().WithMany().HasForeignKey(x => x.ImportBatchId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<WorkItem>().ToTable(t => t.HasCheckConstraint("CK_WorkItem_Core", "(\"OrderAmountCents\" IS NULL OR \"OrderAmountCents\">=0) AND \"Version\">0 AND ((\"SourceKind\"='Manual' AND \"ImportBatchId\" IS NULL AND \"ReceivedDate\" IS NOT NULL) OR (\"SourceKind\"='HistoricalImport' AND \"ImportBatchId\" IS NOT NULL)) AND ((\"DueDateMode\"='Auto' AND \"SpecifiedDueDate\" IS NULL) OR (\"DueDateMode\"='Manual' AND \"SpecifiedDueDate\" IS NOT NULL AND \"EffectiveDueDate\"=\"SpecifiedDueDate\") OR (\"DueDateMode\"='HistoricalUnknown' AND \"SourceKind\"='HistoricalImport' AND \"SpecifiedDueDate\" IS NULL AND \"EffectiveDueDate\" IS NULL)) AND ((\"WorkStatus\"='Completed' AND ((\"CompletedDateKnowledge\"='Known' AND \"CompletedDate\" IS NOT NULL) OR (\"CompletedDateKnowledge\"='Unknown' AND \"SourceKind\"='HistoricalImport' AND \"CompletedDate\" IS NULL AND \"CompletedAt\" IS NULL))) OR (\"WorkStatus\"<>'Completed' AND \"CompletedDateKnowledge\"='NotApplicable' AND \"CompletedDate\" IS NULL AND \"CompletedAt\" IS NULL)) AND ((\"WorkStatus\"='Cancelled' AND \"CancelledFromStatus\" IS NOT NULL) OR (\"WorkStatus\"<>'Cancelled' AND \"CancelledFromStatus\" IS NULL)) AND (\"IsArchived\"=0 OR \"WorkStatus\" IN ('Completed','Cancelled'))"));
        b.Entity<WorkItemRelation>().HasIndex(x => new { x.SourceWorkItemId, x.TargetWorkItemId, x.RelationType }).IsUnique(); b.Entity<WorkItemRelation>().ToTable(t => t.HasCheckConstraint("CK_Relation_NoSelf", "\"SourceWorkItemId\"<>\"TargetWorkItemId\""));
        b.Entity<PaymentTransaction>().HasIndex(x => x.IdempotencyKey).IsUnique(); b.Entity<PaymentTransaction>().Property(x => x.Version).IsConcurrencyToken(); b.Entity<PaymentTransaction>().HasOne<ImportBatch>().WithMany().HasForeignKey(x => x.ImportBatchId).OnDelete(DeleteBehavior.Restrict); b.Entity<PaymentTransaction>().ToTable(t => t.HasCheckConstraint("CK_Payment_Positive", "\"AmountCents\">0 AND ((\"Status\"='Reversed' AND \"ReversalReason\" IS NOT NULL AND trim(\"ReversalReason\")<>'') OR (\"Status\"='Active' AND \"ReversalReason\" IS NULL)) AND ((\"DateKnowledge\"='Known' AND \"TransactionDate\" IS NOT NULL) OR (\"DateKnowledge\"='Unknown' AND \"TransactionDate\" IS NULL)) AND ((\"SourceKind\"='Manual' AND \"ImportBatchId\" IS NULL) OR (\"SourceKind\"='HistoricalImport' AND \"ImportBatchId\" IS NOT NULL))"));
        b.Entity<PaymentAllocation>().HasIndex(x => new { x.PaymentTransactionId, x.WorkItemId }).IsUnique(); b.Entity<PaymentAllocation>().ToTable(t => t.HasCheckConstraint("CK_Allocation_Positive", "\"AmountCents\">0")); b.Entity<PaymentAllocation>().HasOne<PaymentTransaction>().WithMany().HasForeignKey(x => x.PaymentTransactionId).OnDelete(DeleteBehavior.Restrict); b.Entity<PaymentAllocation>().HasOne<WorkItem>().WithMany().HasForeignKey(x => x.WorkItemId).OnDelete(DeleteBehavior.Restrict);
        b.Entity<ExpenseGroup>().HasOne<WorkItem>().WithMany().HasForeignKey(x => x.WorkItemId).OnDelete(DeleteBehavior.Restrict); b.Entity<Expense>().HasOne<ExpenseGroup>().WithMany().HasForeignKey(x => x.ExpenseGroupId).OnDelete(DeleteBehavior.Restrict); b.Entity<Expense>().HasOne<ImportBatch>().WithMany().HasForeignKey(x => x.ImportBatchId).OnDelete(DeleteBehavior.Restrict); b.Entity<Expense>().ToTable(t => t.HasCheckConstraint("CK_Expense_Valid", "\"AmountCents\">0 AND ((\"ExpenseDateKnowledge\"='Known' AND \"ExpenseDate\" IS NOT NULL) OR (\"ExpenseDateKnowledge\"='Unknown' AND \"ExpenseDate\" IS NULL)) AND ((\"PaymentStatus\"='Unpaid' AND \"PaidDate\" IS NULL AND \"PaidDateKnowledge\"='NotApplicable') OR (\"PaymentStatus\"='Paid' AND ((\"PaidDateKnowledge\"='Known' AND \"PaidDate\" IS NOT NULL) OR (\"PaidDateKnowledge\"='Unknown' AND \"PaidDate\" IS NULL)))) AND ((\"Status\"='Voided' AND \"ReversalReason\" IS NOT NULL) OR (\"Status\"='Active' AND \"ReversalReason\" IS NULL)) AND ((\"SourceKind\"='Manual' AND \"ImportBatchId\" IS NULL) OR (\"SourceKind\"='HistoricalImport' AND \"ImportBatchId\" IS NOT NULL))"));
        b.Entity<Shipment>().HasIndex(x => x.WorkItemId).IsUnique(); b.Entity<Shipment>().HasOne<WorkItem>().WithOne().HasForeignKey<Shipment>(x => x.WorkItemId).OnDelete(DeleteBehavior.Restrict); b.Entity<Shipment>().HasOne<ImportBatch>().WithMany().HasForeignKey(x => x.ImportBatchId).OnDelete(DeleteBehavior.Restrict); b.Entity<Shipment>().ToTable(t => t.HasCheckConstraint("CK_Shipment_Valid", "((\"SourceKind\"='Manual' AND \"ImportBatchId\" IS NULL) OR (\"SourceKind\"='HistoricalImport' AND \"ImportBatchId\" IS NOT NULL)) AND (\"FulfillmentPaused\"=0 OR \"ShipmentStatus\"='NotShipped') AND ((\"NoTrackingNumber\"=1 AND \"TrackingNumber\" IS NULL AND \"ShipmentStatus\"<>'NotShipped') OR (\"NoTrackingNumber\"=0 AND \"TrackingNumber\" IS NOT NULL) OR (\"NoTrackingNumber\" IS NULL AND \"TrackingNumber\" IS NULL AND (\"ShipmentStatus\"='NotShipped' OR \"SourceKind\"='HistoricalImport'))) AND ((\"ShipmentStatus\"='NotShipped' AND \"ShippedDateKnowledge\"='NotApplicable' AND \"ShippedDate\" IS NULL AND \"DeliveredDateKnowledge\"='NotApplicable' AND \"DeliveredDate\" IS NULL) OR (\"ShipmentStatus\"='Unknown' AND \"SourceKind\"='HistoricalImport' AND \"ShippedDate\" IS NULL AND \"DeliveredDate\" IS NULL) OR (\"ShipmentStatus\"='Shipped' AND ((\"ShippedDateKnowledge\"='Known' AND \"ShippedDate\" IS NOT NULL) OR (\"ShippedDateKnowledge\"='Unknown' AND \"SourceKind\"='HistoricalImport' AND \"ShippedDate\" IS NULL)) AND \"DeliveredDateKnowledge\"='NotApplicable' AND \"DeliveredDate\" IS NULL) OR (\"ShipmentStatus\"='Delivered' AND ((\"ShippedDateKnowledge\"='Known' AND \"ShippedDate\" IS NOT NULL) OR (\"ShippedDateKnowledge\"='Unknown' AND \"SourceKind\"='HistoricalImport' AND \"ShippedDate\" IS NULL)) AND ((\"DeliveredDateKnowledge\"='Known' AND \"DeliveredDate\" IS NOT NULL) OR (\"DeliveredDateKnowledge\"='Unknown' AND \"SourceKind\"='HistoricalImport' AND \"DeliveredDate\" IS NULL)))) AND (\"DeliveredDate\" IS NULL OR \"ShippedDate\" IS NULL OR \"DeliveredDate\">=\"ShippedDate\")"));
        b.Entity<WorkStatusHistory>().HasOne<WorkItem>().WithMany().HasForeignKey(x => x.WorkItemId).OnDelete(DeleteBehavior.Restrict); b.Entity<WorkStatusHistory>().HasOne<ImportBatch>().WithMany().HasForeignKey(x => x.ImportBatchId).OnDelete(DeleteBehavior.Restrict); b.Entity<ActivityLog>().HasOne<WorkItem>().WithMany().HasForeignKey(x => x.WorkItemId).OnDelete(DeleteBehavior.Restrict); b.Entity<ActivityLog>().HasOne<ImportBatch>().WithMany().HasForeignKey(x => x.ImportBatchId).OnDelete(DeleteBehavior.Restrict); b.Entity<ActivityLog>().ToTable(t => t.HasCheckConstraint("CK_ActivityLog_ImportBatch", "\"SourceKind\"<>'Import' OR \"ImportBatchId\" IS NOT NULL"));
        b.Entity<ImportBatch>().HasIndex(x => x.FileFingerprint).IsUnique(); b.Entity<ImportRowMapping>().HasIndex(x => new { x.ImportBatchId, x.SheetName, x.SourceRowNumber, x.EntityType, x.EntityOrdinal }).IsUnique(); b.Entity<ImportRowMapping>().HasOne<ImportBatch>().WithMany().HasForeignKey(x => x.ImportBatchId).OnDelete(DeleteBehavior.Restrict); b.Entity<Setting>().HasKey(x => x.Key);
        b.Entity<WorkItemRelation>().HasOne<WorkItem>().WithMany().HasForeignKey(x => x.SourceWorkItemId).OnDelete(DeleteBehavior.Restrict); b.Entity<WorkItemRelation>().HasOne<WorkItem>().WithMany().HasForeignKey(x => x.TargetWorkItemId).OnDelete(DeleteBehavior.Restrict);
    }
}
internal sealed class ForeignKeysInterceptor : DbConnectionInterceptor { public override void ConnectionOpened(System.Data.Common.DbConnection c, ConnectionEndEventData e) { using var cmd = c.CreateCommand(); cmd.CommandText = "PRAGMA foreign_keys=ON;"; cmd.ExecuteNonQuery(); } public override async Task ConnectionOpenedAsync(System.Data.Common.DbConnection c, ConnectionEndEventData e, CancellationToken ct = default) { await using var cmd = c.CreateCommand(); cmd.CommandText = "PRAGMA foreign_keys=ON;"; await cmd.ExecuteNonQueryAsync(ct); } }

